{
"@type":"Question",
"name":"Is appliance pickup really free?",
"acceptedAnswer":{
"@type":"Answer",
"text":"Qualifying appliances may be picked up free after review. Approval depends on appliance condition, location, access, local demand and current pickup availability."
}
},
{
"@type":"Question",
"name":"What appliances do you pick up?",
"acceptedAnswer":{
"@type":"Answer",
"text":"Common requests include washers, dryers, washer and dryer sets, refrigerators, stoves, ranges, freezers, dishwashers and other qualifying major household appliances."
}
},
{
"@type":"Question",
"name":"Do you offer free washer and dryer pickup?",
"acceptedAnswer":{
"@type":"Answer",
"text":"Qualifying washers, dryers and washer and dryer sets are priority pickup categories."
}
},
{
"@type":"Question",
"name":"Do you pick up refrigerators?",
"acceptedAnswer":{
"@type":"Answer",
"text":"Qualifying refrigerators may be submitted for review with photos, condition information, city, ZIP code and access details."
}
},
{
"@type":"Question",
"name":"Do you pick up broken appliances?",
"acceptedAnswer":{
"@type":"Answer",
"text":"Working, repairable and non-working appliances can be submitted for review. Pickup is not guaranteed and depends on the individual request and local availability."
}
